import copy


def _strip(value):
    """Deep-copy `value`, dropping every dict key whose value is None, at any depth."""
    if isinstance(value, dict):
        return {k: _strip(v) for k, v in value.items() if v is not None}
    if isinstance(value, list):
        return [_strip(v) for v in value]
    return copy.deepcopy(value)


def _merge(base, override):
    result = {}
    for key, value in base.items():
        if key not in override:
            result[key] = copy.deepcopy(value)
        elif override[key] is None:
            continue
        elif isinstance(value, dict) and isinstance(override[key], dict):
            result[key] = _merge(value, override[key])
        else:
            result[key] = _strip(override[key])
    for key, value in override.items():
        if key not in base and value is not None:
            result[key] = _strip(value)
    return result


def deep_merge(base, override):
    """Layer `override` over `base`.

    Returns a new dict. Neither argument is modified, and the result shares no
    dict or list objects with either argument. Dicts present on both sides are
    merged recursively; any other override value replaces the base value
    (lists are replaced, not joined). A key whose override value is None is
    removed from the result, at every depth.
    """
    return _merge(base, override)
